export interface ResumePlan {
  /** The sidecar found, if it names this URL. */
  stored: PartialDownloadMeta | null;
  /** Trusted byte intervals already on disk (merged, disjoint). */
  done: ByteRange[];
  /** Declared length from the sidecar, `0` when unknown or nothing is kept. */
  total: number;
  /** First byte the lead request asks for. */
  offset: number;
  /** Whether the lead carries a `Range` header at all. */
  sentRange: boolean;
  leadHeaders: Record<string, string>;
}

/**
 * Decide what a new attempt can build on. Only a sidecar naming this URL
 * with intervals that fit both the declared length and the file on disk
 * counts; anything else is discarded and the attempt starts from zero.
 */
export function describeResume(
  url: string,
  destPath: string,
  headers: Record<string, string>,
): ResumePlan {
  const stored = readPartialMeta(destPath);
  let done: ByteRange[] =
    stored && stored.url === url ? completedRanges(destPath, stored) : [];
  const total = done.length > 0 && stored ? stored.total : 0;
  const first = done[0];
  if (first && total === 0 && (done.length !== 1 || first[0] !== 0)) {
    // No declared length and bytes that are not one prefix: nothing to
    // ask the server for.
    done = [];
  }
  if (done.length === 0) discardPartialDownload(destPath);
  const holes: ByteRange[] =
    !first || done.length === 0
      ? []
      : total > 0
        ? holesIn(done, total)
        : [[first[1], Infinity]];
  // Where the lead request starts: the first byte we do not have. With
  // every byte present this is `total` — the range request then asks
  // for nothing, and the 416 branch publishes the file once the server
  // has confirmed it still is that file. A partial whose first hole is
  // at byte 0 (the lead had not delivered when the last run died) still
  // sends a range: a plain GET would read as "start over".
  const offset = done.length === 0 ? 0 : ((holes[0]?.[0] ?? total) + 1);
  const sentRange = done.length > 0;
  const leadHeaders = { ...headers };
  if (sentRange) {
    leadHeaders.Range = `bytes=${offset}-`;
    // `If-Range` makes a server that still has the same file answer 206
    // and one that has a new one answer 200 with the whole body — the
    // restart case, handled without a second round-trip.
    const validator = stored?.etag ?? stored?.lastModified;
    if (validator) leadHeaders["If-Range"] = validator;
  }
  return {
    stored,
    done,
    total: done.length > 0 ? total : 0,
    offset,
    sentRange,
    leadHeaders,
  };
}

/** Publish the finished `.part` and report the terminal number once. */
export function finalize(
  destPath: string,
  transferred: number,
  total: number,
  onProgress?: (percent: number, transferred: number, total: number) => void,
): void {
  fs.renameSync(resolvePartialPath(destPath), destPath);
  discardPartialDownload(destPath);
  // A 416-finalised partial never streamed, so it never reported; and a
  // streamed one may have emitted its last progress inside the throttle
  // window. Either way the terminal number goes out exactly once here.
  if (total > 0 && transferred === total) {
    onProgress?.(100, transferred, total);
  }
}

import * as fs from "node:fs";

/** A half-open byte interval `[start, end)`. */
export type ByteRange = readonly [start: number, end: number];

/**
 * Sidecar next to the `.part` file: what the partial bytes belong to.
 *
 * `done` lists the byte intervals already on disk. A segmented download
 * fills the file out of order, so "how much is here" is the sum of
 * these intervals, not the file size. `null` marks a sidecar written by
 * a pre-segment build: its bytes are one prefix, measured by file size.
 */
export interface PartialDownloadMeta {
  url: string;
  /** Total length the server declared, or `0` when it did not. */
  total: number;
  etag: string | null;
  lastModified: string | null;
  done: ByteRange[] | null;
}

/**
 * On-disk shape of a current sidecar. The URL sits under `source`, not
 * `url`, on purpose: a pre-segment build reads `url` and treats the
 * `.part` file size as the resume offset. Fed a sparse, out-of-order
 * partial that way it would append the tail of the file onto a hole and
 * publish a GGUF that crashes llama-server. Without `url` it sees no
 * usable partial and starts over instead — slower, but correct.
 */
const PARTIAL_META_VERSION = 2;

export function resolvePartialPath(destPath: string): string {
  return `${destPath}.part`;
}

export function resolvePartialMetaPath(destPath: string): string {
  return `${destPath}.part.json`;
}

export function partialSize(destPath: string): number {
  try {
    return fs.statSync(resolvePartialPath(destPath)).size;
  } catch {
    return 0;
  }
}

export function rmQuiet(path: string): void {
  try {
    fs.rmSync(path, { force: true });
  } catch {
    /* ignore */
  }
}

/** Sorted, disjoint, non-empty intervals; touching ones are joined. */
export function mergeRanges(ranges: readonly ByteRange[]): ByteRange[] {
  const sorted = ranges
    .filter(([start, end]) => end > start)
    .slice()
    .sort((a, b) => a[0] - b[0]);
  const out: Array<[number, number]> = [];
  for (const [start, end] of sorted) {
    const last = out[out.length - 1];
    if (last && start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      out.push([start, end]);
    }
  }
  return out;
}

export function sumRanges(ranges: readonly ByteRange[]): number {
  let sum = 0;
  for (const [start, end] of ranges) sum += end - start;
  return sum;
}

/** The complement of `done` (already merged) inside `[0, total)`. */
export function holesIn(
  done: readonly ByteRange[],
  total: number,
): ByteRange[] {
  const holes: ByteRange[] = [];
  let cursor = 0;
  for (const [start, end] of done) {
    if (start > cursor) holes.push([cursor, Math.min(start, total)]);
    cursor = Math.max(cursor, end);
    if (cursor >= total) break;
  }
  if (cursor < total) holes.push([cursor, total]);
  return holes;
}

function parseRanges(raw: unknown): ByteRange[] | null {
  if (!Array.isArray(raw)) return null;
  const out: ByteRange[] = [];
  for (const item of raw) {
    if (!Array.isArray(item) || item.length !== 2) return null;
    const [start, end] = item as unknown[];
    if (
      typeof start !== "number" ||
      typeof end !== "number" ||
      !Number.isInteger(start) ||
      !Number.isInteger(end) ||
      start < 0 ||
      end < start
    ) {
      return null;
    }
    out.push([start, end]);
  }
  return mergeRanges(out);
}

